async def act(page):
    import re
    import urllib.parse

    # Utility to safely click a locator if present and clickable
    async def safe_click(locator, timeout=3000):
        try:
            if await locator.count() > 0:
                await locator.nth(0).click(timeout=timeout)
                await page.wait_for_timeout(250)
                return True
        except Exception:
            return False
        return False

    # 1) Close any visible dialog/pop-up that may block interactions.
    try:
        # Prefer dialog role if present
        dialog = page.get_by_role("dialog")
        if await dialog.count() > 0:
            # try any button inside the dialog first
            dlg_btns = dialog.get_by_role("button")
            if await dlg_btns.count() > 0:
                await safe_click(dlg_btns)
            else:
                # fall back to a generic close button by name
                close_btn = page.get_by_role("button", name=re.compile(r"^(?:close|dismiss|×|x)$", re.I))
                await safe_click(close_btn)
        else:
            # No dialog role - try generic close controls site-wide
            close_btn = page.get_by_role("button", name=re.compile(r"^(?:close|dismiss|×|x|ok)$", re.I))
            await safe_click(close_btn)
    except Exception:
        # Non-fatal; proceed
        await page.wait_for_timeout(200)

    # 2) Locate the complementary region which contains the search widget
    comp = page.get_by_role("complementary")
    if await comp.count() == 0:
        print("complementary region not found; cannot use visible search")
        return

    # 3) Find the search input inside the complementary region
    search_input = comp.get_by_role("searchbox", name="Search")
    if await search_input.count() == 0:
        alt_tb = comp.get_by_role("textbox")
        if await alt_tb.count() > 0:
            search_input = alt_tb.nth(0)

    if await search_input.count() == 0:
        print("Search input not found in complementary region")
        return

    # 4) Fill search keyword
    keyword = "VSCodium"
    await search_input.fill(keyword)

    # 5) Activate the search: prefer a Search button inside the complementary region
    search_btn = comp.get_by_role("button", name=re.compile(r"search", re.I))
    clicked = False
    if await search_btn.count() > 0:
        clicked = await safe_click(search_btn)
    if not clicked:
        # fallback: first button inside complementary region
        first_btn = comp.get_by_role("button")
        if await first_btn.count() > 0:
            clicked = await safe_click(first_btn)
    if not clicked:
        # last resort: press Enter in the search input
        try:
            await search_input.press("Enter")
            clicked = True
        except Exception:
            clicked = False

    # 6) Wait briefly for results to appear in main (or for network idle)
    main = page.get_by_role("main")
    try:
        if await main.count() > 0:
            await main.wait_for(state="visible", timeout=4000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle", timeout=4000)
        except Exception:
            pass

    # 7) Look for the target post among articles in <main>
    target_tokens = ["i ditched", "vscodium", "vs code", "i ditched vs code"]
    post_url = None

    if await main.count() > 0:
        articles = main.get_by_role("article")
        art_count = await articles.count()
        for i in range(art_count):
            article = articles.nth(i)
            links = article.get_by_role("link")
            ln_count = await links.count()
            for j in range(ln_count):
                try:
                    text = (await links.nth(j).inner_text() or "").lower()
                except Exception:
                    text = ""
                if any(tok in text for tok in target_tokens):
                    href = await links.nth(j).get_attribute("href")
                    if href:
                        post_url = urllib.parse.urljoin(page.url, href)
                        break
            if post_url:
                break

    # 8) If not found in main, check recent-post links inside complementary region
    if not post_url:
        comp_links = comp.get_by_role("link")
        cl_count = await comp_links.count()
        for i in range(cl_count):
            try:
                txt = (await comp_links.nth(i).inner_text() or "").lower()
            except Exception:
                txt = ""
            if any(tok in txt for tok in target_tokens):
                href = await comp_links.nth(i).get_attribute("href")
                if href:
                    post_url = urllib.parse.urljoin(page.url, href)
                    break

    if not post_url:
        print("Target post not found after searching the site.")
        return

    # 9) Navigate to the discovered post URL
    await page.goto(post_url)

    # Allow page to settle
    try:
        await page.wait_for_load_state("networkidle", timeout=4000)
    except Exception:
        await page.wait_for_timeout(400)

    # 10) Close any popup/dialog on the post page
    try:
        dlg = page.get_by_role("dialog")
        if await dlg.count() > 0:
            btns = dlg.get_by_role("button")
            if await btns.count() > 0:
                await safe_click(btns)
        else:
            close_btn = page.get_by_role("button", name=re.compile(r"^(?:close|dismiss|×|x)$", re.I))
            await safe_click(close_btn)
    except Exception:
        await page.wait_for_timeout(200)

    # 11) Locate comment textbox: prefer labelled 'Comment', then any textbox
    comment_box = page.get_by_role("textbox", name=re.compile(r"comment", re.I))
    if await comment_box.count() == 0:
        # try inside main
        if await main.count() > 0:
            main_tbs = main.get_by_role("textbox")
            if await main_tbs.count() > 0:
                comment_box = main_tbs.nth(0)
    if await comment_box.count() == 0:
        any_tb = page.get_by_role("textbox")
        if await any_tb.count() > 0:
            comment_box = any_tb.nth(0)

    if await comment_box.count() == 0:
        print("Could not find a comment textbox on the post page.")
        return

    # 12) Fill the exact requested comment text
    await comment_box.fill("This gives me a new angle to consider.")

    # 13) Try to fill name and email fields if present
    async def try_fill(labels, value):
        for lbl in labels:
            loc = page.get_by_role("textbox", name=lbl)
            if await loc.count() > 0:
                await loc.nth(0).fill(value)
                return True
        # try inside main region as well
        if await main.count() > 0:
            for lbl in labels:
                loc = main.get_by_role("textbox", name=lbl)
                if await loc.count() > 0:
                    await loc.nth(0).fill(value)
                    return True
        return False

    await try_fill(["Name", "Your name", "Display name", "Author"], "Playwright User")
    await try_fill(["Email", "E-mail", "Your email", "Email address"], "playwright@example.com")

    # 14) Locate a submit button for posting the comment
    submit_btn = None
    possible_patterns = [r"post comment", r"submit comment", r"submit", r"send", r"leave a comment", r"comment"]
    for pat in possible_patterns:
        btn = page.get_by_role("button", name=re.compile(pat, re.I))
        if await btn.count() > 0:
            submit_btn = btn.nth(0)
            break

    # Prefer a button inside main if not found globally
    if not submit_btn and await main.count() > 0:
        main_btns = main.get_by_role("button")
        if await main_btns.count() > 0:
            submit_btn = main_btns.nth(0)

