    if not submit_btn:
        all_btns = page.get_by_role("button")
        if await all_btns.count() > 0:
            submit_btn = all_btns.nth(0)

    if not submit_btn:
        print("Could not locate a submit control to post the comment.")
        return

    # 15) Click the submit control to post the comment
    try:
        await submit_btn.click()
        await page.wait_for_timeout(1200)
        print("Comment submission attempted.")
    except Exception as e:
        print(f"Error clicking submit: {e}")

